static void tiziano_ae0_select_wrapper_inputs(void **awb_cfg, void **corr_cfg,
					      int32_t **r_corr, int32_t **b_corr,
					      int32_t *corr_param_a,
					      int32_t *corr_param_b);

static void tiziano_ae0_select_mix_weights(int32_t *mix_r, int32_t *mix_b)
{
    const uint32_t *scene_cfg = tiziano_ae0_scene_config();
    uint32_t processing_mode = scene_cfg[0];
    uint32_t selector = _ae_stat.data[3];
    int32_t sel_r = 1;
    int32_t sel_b = 1;

    /* OEM Tiziano_ae0_fpga passes the odd scene-config entry as the R
     * multiplier (ae0_weight_mean2 arg19) and the following even entry as
     * the B multiplier (arg20).  Keeping this order matters on a Bayer scene:
     * reversing the pair makes the much smaller R statistics count twice and
     * biases AE toward excess exposure. */
    if (processing_mode == 0) {
        sel_r = 1;
        sel_b = 1;
    } else if (processing_mode == 1) {
        sel_r = (int32_t)scene_cfg[5];
        sel_b = (int32_t)scene_cfg[6];
    } else if (selector == 2) {
        sel_r = (int32_t)scene_cfg[5];
        sel_b = (int32_t)scene_cfg[6];
    } else if (selector == 1) {
        sel_r = (int32_t)scene_cfg[7];
        sel_b = (int32_t)scene_cfg[8];
    } else if (selector == 0) {
        sel_r = (int32_t)scene_cfg[9];
        sel_b = (int32_t)scene_cfg[10];
    } else {
        sel_r = 0;
        sel_b = 0;
    }

    *mix_r = sel_r;
    *mix_b = sel_b;
}

static void tiziano_ae0_select_wrapper_inputs(void **awb_cfg, void **corr_cfg,
					      int32_t **r_corr, int32_t **b_corr,
					      int32_t *corr_param_a,
					      int32_t *corr_param_b)
{
    const int wdr = (data_b0e10 != 0);

    if (awb_cfg)
        *awb_cfg = wdr ? (void *)&_scene_para_wdr : (void *)&_scene_para;
    if (corr_cfg)
        *corr_cfg = wdr ? (void *)&ae_scene_mode_th_wdr
                        : (void *)&ae_scene_mode_th;
    if (r_corr)
        *r_corr = (int32_t *)_scene_roui_weight.data;
    if (b_corr)
        *b_corr = (int32_t *)_scene_roi_weight.data;

    if (corr_param_a)
        *corr_param_a = 0;
    if (corr_param_b)
        *corr_param_b = 0;
}

