        /* Strength arrays 1..16 */
        case 0x111: src = sdns_wdr_en ? sdns_h_s_wdr_arrays[0]  : sdns_h_s_arrays[0];  len = 0x40; break;
        case 0x112: src = sdns_wdr_en ? sdns_h_s_wdr_arrays[1]  : sdns_h_s_arrays[1];  len = 0x40; break;
