static int tiziano_s_wb_algo(uint32_t mode)
{
	if (mode == 1) {
		awb_algo_mode = 1;
	} else {
		if (mode != 0 && mode != 2) {
			pr_err("%s:%d::Can not support this awb algo mode!!!\n",
			       __func__, __LINE__);
			return -1;
		}

		awb_algo_mode = 0;
	}

	return tiziano_awb_set_hardware_param();
}

