{
    tawb_custom_en = enable;
    return 0;
}

int tisp_awb_algo_handle(void *ctx)
{
    /* Vendor: if (*(arg1 + 8) != 1) return 1 */
    if (!ctx) return -EINVAL;
    uint32_t flag = 0, r_gain = 0, b_gain = 0;
    memcpy(&flag,  (char *)ctx + 0x8,  4);
    if (flag != 1) return 1;

    /* Gains at offsets 0xc (R) and 0x10 (B) per decompile */
    memcpy(&r_gain, (char *)ctx + 0xc,  4);
    memcpy(&b_gain, (char *)ctx + 0x10, 4);

    /* Call vendor attribute setter exactly like binary: tisp_s_wb_attr(1, r, b, 0,0,0) */
    return tisp_s_wb_attr(1, r_gain, b_gain, 0, 0, 0);
}

int tisp_awb_algo_deinit(void)
{
    return tisp_awb_deinit();
}

/* OEM EXACT: tisp_rdns_awb_gain_par_cfg — write RDNS AWB gain registers.
 * Decompiled from OEM at 0x58b14. */
static int tisp_rdns_awb_gain_par_cfg(void)
{
    uint32_t *arr = (uint32_t *)rdns_awb_gain_par_cfg_array;
    system_reg_write(0x3000, (arr[1] << 16) | arr[0]);
    system_reg_write(0x3004, (arr[3] << 16) | arr[2]);
    return 0;
}

/* VDB2 OEM 0x59a00: keep the RDNS colour-gain normalization in step with
 * AWB.  Tiziano_awb_set_gain passes the upper halfwords of its packed AWB
 * registers here; those halfwords are the constant 0x0400 marker, not the
 * live red/blue gains in the low halfwords.  Consequently stock programs
 * unity RDNS gains (0x40 after >> 4) and their Q6 reciprocals (1). */
static int tisp_rdns_awb_gain_updata(uint32_t gain_gr, uint32_t gain_gb)
{
    uint32_t gr = gain_gr >> 4;
    uint32_t gb = gain_gb >> 4;
    uint32_t gr_inv = fix_point_div_32(6, 1, gr);
    uint32_t gb_inv = fix_point_div_32(6, 1, gb);

    system_reg_write(0x3000, (gb << 16) | gr);
    system_reg_write(0x3004, (gb_inv << 16) | gr_inv);
    system_reg_write(0x30ac, 1);
    return 0;
}

/* OEM EXACT: JZ_Isp_Awb_Reg2par — unpack AWB HW register block into parameter struct.
 * Decompiled from OEM at 0x17250. Complex bit-field extraction from AWB stat registers. */
static int JZ_Isp_Awb_Reg2par(uint32_t *out, const uint32_t *regs)
{
    uint32_t r0 = regs[0];
    int i, j;
    uint32_t lo_vals[16], hi_vals[16];

    /* Unpack 4 register pairs (regs[5..8]) into 16 7-bit values each */
    for (i = 0; i < 4; i++) {
        uint32_t lo_word = regs[i + 5 - 4]; /* regs[1..4] adjusted */
        uint32_t hi_word = regs[i + 5];
        for (j = 0; j < 4; j++) {
            int shift = j * 8; /* 2-bit pairs, but 7-bit fields at 8-bit spacing */
            lo_vals[i * 4 + j] = (lo_word >> shift) & 0x7f;
            hi_vals[i * 4 + j] = (hi_word >> shift) & 0x7f;
        }
    }

    out[3] = r0 >> 28;
    out[0] = r0 & 0x7ff;
    out[1] = (r0 >> 12) & 0xf;
    out[2] = (r0 << 5) >> 21;

    for (i = 0; i < 15; i++) {
        out[4 + i] = lo_vals[i];
        out[4 + 15 + i] = hi_vals[i];
    }

    out[0x26] = regs[0xb] & 0xffff;
    out[0x28] = regs[0xc] & 0xffff;
    out[0x22] = regs[9] & 0xfff;
    out[0x23] = (regs[9] >> 16) & 0xfff;
    out[0x24] = regs[0xa] & 0xfff;
    out[0x25] = (regs[0xa] >> 16) & 0xfff;
    out[0x27] = regs[0xb] >> 16;
    out[0x29] = regs[0xc] >> 16;
    out[0x2a] = regs[0xd] & 0xff;
    out[0x2b] = (regs[0xd] >> 8) & 0xff;
    out[0x2c] = (regs[0xd] >> 16) & 0xf;
    return out[0x2c];
}

