	dmsc_hv_thres_1_val = tisp_simple_intp(hi, lo, dmsc_hv_thres_1_curve);
	dmsc_hv_stren_val = tisp_simple_intp(hi, lo, dmsc_hv_stren_curve);
	dmsc_aa_thres_1_val = tisp_simple_intp(hi, lo, dmsc_aa_thres_1_curve);
