	dmsc_sp_ud_flat_thres_val = tisp_simple_intp(hi, lo, dmsc_sp_ud_flat_thres_curve);
	dmsc_sp_ud_flat_stren_val = tisp_simple_intp(hi, lo, dmsc_sp_ud_flat_stren_curve);
