    sdns_grad_zx_thres_intp = tisp_simple_intp(gain_hi, gain_lo, sdns_grad_zx_thres_array_now);
    sdns_grad_zy_thres_intp = tisp_simple_intp(gain_hi, gain_lo, sdns_grad_zy_thres_array_now);
