#undef INTP
#undef INTP_NULL

static int tisp_mdns_intp_reg_refresh(uint32_t interp_key)
{
    /* OEM EXACT: tisp_mdns_intp(arg1) then register writes */
    tisp_mdns_intp(interp_key);
    system_reg_write(0x7804, 0x110);
    tisp_mdns_y_3d_param_cfg();
    tisp_mdns_y_2d_param_cfg();
    tisp_mdns_c_3d_param_cfg();
    tisp_mdns_c_2d_param_cfg();
    return 0;
}

/* OEM: 0x32ae0 - tisp_mdns_top_func_cfg */
static int tisp_mdns_top_func_cfg(int enable)
{
    u32 ctrl = 0x101;
    u32 top1;
    static int top_func_diag_count;

    if (enable) {
        /* OEM EXACT: Full MDNS control with both Y and UV processing.
         * Previously UV was disabled due to pink tint with GIB active,
         * but GIB is currently bypassed so UV temporal denoise is safe. */
        ctrl = 0x10001 |
               (mdns_y_sf_cur_en_array << 4) |
               (mdns_y_sf_ref_en_array << 8) |
               (mdns_y_filter_en_array << 12) |
               (mdns_uv_sf_cur_en_array << 20) |
               (mdns_uv_sf_ref_en_array << 24) |
               (mdns_uv_filter_en_array << 28);
    }

    /* PINK_DIAG: trace each top_func_cfg call to see what value is written
     * vs what the register reads back. Helps spot double-buffer/mask issues. */
    if (top_func_diag_count < 6) {
        top_func_diag_count++;
        pr_info("MDNS_TOP_CFG[%d]: enable=%d arrays=%u/%u/%u/%u/%u/%u "
                "ctrl=0x%08x (about to write 0x7810)\n",
                top_func_diag_count, enable,
                mdns_y_sf_cur_en_array, mdns_y_sf_ref_en_array,
                mdns_y_filter_en_array, mdns_uv_sf_cur_en_array,
                mdns_uv_sf_ref_en_array, mdns_uv_filter_en_array,
                ctrl);
    }

    system_reg_write(0x7810, ctrl);

    /* OEM reads mdns_y_con_thres_intp (pre-computed global) */
    top1 = mdns_y_con_thres_intp |
           (mdns_bgm_enable_array << 4) |
           (mdns_ref_wei_byps_array << 8) |
           (mdns_sta_group_num_array << 12) |
           (mdns_psn_enable_array << 16) |
           (mdns_psn_max_num_array << 20);

    /*
     * The shipping SC2336 pipeline leaves the low confidence-threshold bit
     * and pixel-sample-noise path disabled in linear mode.  Enabling them
     * turns stable, low-contrast walls into a frame-varying texture even
     * though exposure and gain are constant.  This mask is taken from a
     * same-camera, same-scene OEM register oracle (0x7814 = 0x00f01100).
     */
    if (tisp_sc2336_oem_profile_active() && !mdns_wdr_en)
        top1 &= ~0x00010001U;

    system_reg_write(0x7814, top1);
    system_reg_write(0x7808, (mdns_uv_debug_array << 5) | mdns_y_debug_array);

    if (top_func_diag_count <= 6 && top_func_diag_count >= 1) {
        pr_info("MDNS_TOP_CFG[%d]: top1=0x%08x debug=0x%08x | readback "
                "0x7810=0x%08x 0x7814=0x%08x 0x7808=0x%08x\n",
                top_func_diag_count, top1,
                (mdns_uv_debug_array << 5) | mdns_y_debug_array,
                system_reg_read(0x7810), system_reg_read(0x7814),
                system_reg_read(0x7808));
    }
    return 0;
}

static int tisp_mdns_top_func_refresh(void)
{
    system_reg_write(0x7818, 1);
    return 0;
}

static int tisp_mdns_bypass(int bypass)
{
    tisp_mdns_top_func_cfg(bypass ? 0 : 1);
    tisp_mdns_top_func_refresh();
    tisp_mdns_reg_trigger();
    return 0;
}

/* OEM EXACT: tisp_mdns_refresh — simple wrapper */
int tisp_mdns_refresh(uint32_t gain)
{
    tisp_mdns_par_refresh(gain, 0x100);
    return 0;
}

static int tisp_mdns_par_refresh(uint32_t interp_key, uint32_t threshold)
{
    u32 diff;

    if (mdns_last_refresh_key == 0xffffffff) {
        mdns_last_refresh_key = interp_key;
        data_9a9d0 = interp_key;
        tisp_mdns_all_reg_refresh(interp_key);
        tisp_mdns_top_func_refresh();
        tisp_mdns_reg_trigger();
        return 0;
    }

    diff = (mdns_last_refresh_key >= interp_key)
        ? (mdns_last_refresh_key - interp_key)
        : (interp_key - mdns_last_refresh_key);

    if (diff >= threshold) {
        mdns_last_refresh_key = interp_key;
        data_9a9d0 = interp_key;
        tisp_mdns_intp_reg_refresh(interp_key);
        tisp_mdns_reg_trigger();
    }

    return 0;
}

/* tisp_mdns_all_reg_refresh - OEM EXACT call sequence */
static int tisp_mdns_all_reg_refresh(uint32_t interp_key)
{
    /* OEM EXACT: intp → 0x7804=0x110 → y_3d → y_2d → c_3d → c_2d → top_func_cfg(1) */
    tisp_mdns_intp(interp_key);
    system_reg_write(0x7804, 0x110);
    tisp_mdns_y_3d_param_cfg();
    tisp_mdns_y_2d_param_cfg();
    tisp_mdns_c_3d_param_cfg();
    tisp_mdns_c_2d_param_cfg();
    tisp_mdns_top_func_cfg(1);

    return 0;
}

/* tisp_mdns_reg_trigger - Binary Ninja EXACT implementation */
static int tisp_mdns_reg_trigger(void)
{
    system_reg_write(0x7804, 0x111);
    return 0;
}

/* OEM tisp_s_BacklightComp (0x63ac4 in the stock T31 module).
 *
 * These scalar libimp controls are also the runtime initialization path for
 * the AE scene parameters.  In particular, setting backlight compensation
 * to zero changes scene_para[6] from the tuning-file value 2 to 1.  The stock
 * module updates its embedded active tuning bank and the live AE structure;
 * it deliberately does not alter the allocated day/night source banks. */
int tisp_s_BacklightComp(int comp_level)
{
    struct scene_para scene;
    int param_size = sizeof(scene);

    if (tparams_active)
        memcpy(&scene, (u8 *)tparams_active + TISP_PARAM_AE_SCENE_OFFSET,
               sizeof(scene));
    else
        memcpy(&scene, &_scene_para, sizeof(scene));

    scene.data[0] = 1;
    scene.data[5] = comp_level + 1;
    scene.data[6] = 1;

    if (tparams_active)
        memcpy((u8 *)tparams_active + TISP_PARAM_AE_SCENE_OFFSET, &scene,
               sizeof(scene));
    tisp_ae_param_array_set(0xc, &scene, &param_size);
    tisp_ae_trig();
    return 0;
}
