/* OEM EXACT: JZ_Isp_Ae_Reg2par (0x4e9a0) — unpack AE register values to params */
int JZ_Isp_Ae_Reg2par(uint32_t *out, uint32_t *regs)
{
    uint32_t r0 = regs[0];
    uint32_t r9 = regs[9];
    uint32_t row_data[16], col_data[16];
    int i, j;

    for (i = 0; i < 4; i++) {
        uint32_t rv = regs[i + 5 - 4]; /* rows */
        uint32_t cv = regs[i + 5];     /* cols */
        for (j = 0; j < 4; j++) {
            int shift = j * 2;
            row_data[i * 4 + j] = (rv >> shift) & 0x7f;
            col_data[i * 4 + j] = (cv >> shift) & 0x7f;
        }
    }

    out[0] = r0 & 0x7ff;                     /* bits [10:0]  = 11 bits */
    out[1] = (r0 >> 12) & 0xf;                /* bits [15:12] = 4 bits  */
    out[2] = (r0 << 5) >> 21;                 /* bits [26:16] = 11 bits */
    out[3] = r0 >> 28;                        /* bits [31:28] = 4 bits  */

    for (i = 0; i < 15; i++) {
        out[4 + i] = row_data[i];
        out[4 + 15 + i] = col_data[i];
    }

    out[0x22] = r9 & 0xff;
    out[0x23] = (r9 >> 8) & 0xff;
    out[0x24] = (r9 >> 16) & 0xf;
    out[0x25] = (r9 >> 20) & 0xf;
    return out[0x25];
}

